(5680613, 825840, 109245, '<td valign="top">This photo is amazing<br/>But, unfortunately, not really low key.</td>', 'This photo is amazingBut, unfortunately, not really low key.', '2009-10-08 15:20:33.000000', NULL, 1),
(5680615, 826170, 12674, '<td valign="top">A tough subject to depict as low key because of its bright color and styling. The crop is also a bit unusual.</td>', 'A tough subject to depict as low key because of its bright color and styling. The crop is also a bit unusual.', '2009-10-08 15:20:54.000000', NULL, 1),
(5680618, 825125, 109245, '<td valign="top">WoW<br/>...<br/>Speechless<br/> <br/>This is perfection.<br/> <br/>10 =]</td>', 'WoW...Speechless This is perfection. 10 =]', '2009-10-08 15:26:56.000000', NULL, 1),
(5680622, 825630, 12674, '<td valign="top">The subject or feeling you''re trying to convey is unclear to me, I think because of the lighting. You might try a long exposure without the use of the flash.</td>', 'The subject or feeling you''re trying to convey is unclear to me, I think because of the lighting. You might try a long exposure without the use of the flash.', '2009-10-08 15:29:11.000000', NULL, 1),
(5680626, 826157, 12674, '<td valign="top">I couldn''t recognize the subject without your title. A little more lighting on the front side would''ve provided more definition, at least on my monitor.</td>', 'I couldn''t recognize the subject without your title. A little more lighting on the front side would''ve provided more definition, at least on my monitor.', '2009-10-08 15:32:58.000000', NULL, 1),
(5680630, 826105, 12674, '<td valign="top">Image is a bit too dark on my monitor to make out your subject.</td>', 'Image is a bit too dark on my monitor to make out your subject.', '2009-10-08 15:35:27.000000', NULL, 1),
(5680631, 826190, 12674, '<td valign="top">Neat subject and composition.  The background on left competes for some of my attention.</td>', 'Neat subject and composition.  The background on left competes for some of my attention.', '2009-10-08 15:38:10.000000', NULL, 1),
(5680632, 825815, 12674, '<td valign="top">Crop is a bit distracting. Might''ve been nice to see more of the person holding the baby.</td>', 'Crop is a bit distracting. Might''ve been nice to see more of the person holding the baby.', '2009-10-08 15:40:45.000000', NULL, 1),
(5680638, 825958, 12674, '<td valign="top">Now that''s an interesting subject, I like it. It might add interest to crop it in a way that the moon wasn''t so centered.</td>', 'Now that''s an interesting subject, I like it. It might add interest to crop it in a way that the moon wasn''t so centered.', '2009-10-08 15:46:12.000000', NULL, 1),
(5680794, 826080, 68956, '<td valign="top">I like this - the white dots look like little stars as though she''s floating through space :)</td>', 'I like this - the white dots look like little stars as though she''s floating through space :)', '2009-10-08 17:47:46.000000', NULL, 1),
(5680796, 826064, 68956, '<td valign="top">Lovely end of the day feel, not a fan of centered composition, but it works well here :)</td>', 'Lovely end of the day feel, not a fan of centered composition, but it works well here :)', '2009-10-08 17:49:21.000000', NULL, 1),
(5680813, 826235, 68956, '<td valign="top">Some low key images are just underexposed - this one is but it''s made it into what I think is a beautiful low key image. It''s wonderfully timeless and has a touch of death about it (sorry Sara!) a sort of Victorian gothic - lovely :)</td>', 'Some low key images are just underexposed - this one is but it''s made it into what I think is a beautiful low key image. It''s wonderfully timeless and has a touch of death about it (sorry Sara!) a sort of Victorian gothic - lovely :)', '2009-10-08 17:54:45.000000', NULL, 1),
(5680816, 826144, 68956, '<td valign="top">Nice detail and composition :)</td>', 'Nice detail and composition :)', '2009-10-08 17:55:24.000000', NULL, 1),
(5680817, 826179, 68956, '<td valign="top">I like the feel of this - I think there''s a touch of softness- maybe a bit of noise would help with that and increase the atmosphere at the same time? :)</td>', 'I like the feel of this - I think there''s a touch of softness- maybe a bit of noise would help with that and increase the atmosphere at the same time? :)', '2009-10-08 17:57:13.000000', NULL, 1),
(5680818, 826209, 68956, '<td valign="top">Beautiful image and successfully low key :)</td>', 'Beautiful image and successfully low key :)', '2009-10-08 17:57:52.000000', NULL, 1),
(5680819, 826074, 68956, '<td valign="top">Gosh, an amazingly still piece of water, very striking :)</td>', 'Gosh, an amazingly still piece of water, very striking :)', '2009-10-08 17:59:21.000000', NULL, 1),
(5680821, 826122, 68956, '<td valign="top">I just love the string - really made me laugh - great image!</td>', 'I just love the string - really made me laugh - great image!', '2009-10-08 18:00:15.000000', NULL, 1),
(5680823, 826101, 68956, '<td valign="top">A nice clear, low key portrait of your old friend :)</td>', 'A nice clear, low key portrait of your old friend :)', '2009-10-08 18:00:49.000000', NULL, 1),
(5680824, 825098, 68956, '<td valign="top">That is lovely, well done :)</td>', 'That is lovely, well done :)', '2009-10-08 18:01:42.000000', NULL, 1),
(5680825, 825440, 68956, '<td valign="top">Lovely composition , maybe needs to be a tad sharper on Big Ben, great idea though :)</td>', 'Lovely composition , maybe needs to be a tad sharper on Big Ben, great idea though :)', '2009-10-08 18:03:11.000000', NULL, 1),
(5680827, 825867, 68956, '<td valign="top">This has worked well as low key :)</td>', 'This has worked well as low key :)', '2009-10-08 18:04:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5680829, 825506, 68956, '<td valign="top">what an expression!</td>', 'what an expression!', '2009-10-08 18:06:54.000000', NULL, 1),
(5680838, 826137, 12674, '<td valign="top">Very pretty shot. I might''ve cropped it to eliminate the vase at the bottom.</td>', 'Very pretty shot. I might''ve cropped it to eliminate the vase at the bottom.', '2009-10-08 18:22:07.000000', NULL, 1),
(5680846, 826189, 12674, '<td valign="top">Beautiful shot, one of my favorites.</td>', 'Beautiful shot, one of my favorites.', '2009-10-08 18:25:42.000000', NULL, 1),
(5680849, 825496, 12674, '<td valign="top">A nice clear shot but the subject isn''t very interesting.</td>', 'A nice clear shot but the subject isn''t very interesting.', '2009-10-08 18:28:40.000000', NULL, 1),
(5680850, 826144, 12674, '<td valign="top">Very nice! Beautiful subdued color, texture, and composition.</td>', 'Very nice! Beautiful subdued color, texture, and composition.', '2009-10-08 18:29:59.000000', NULL, 1),
(5680851, 826123, 12674, '<td valign="top">Very nice subdued tonal range and texture.</td>', 'Very nice subdued tonal range and texture.', '2009-10-08 18:31:59.000000', NULL, 1),
(5680853, 826075, 12674, '<td valign="top">Lovely shot, one of my favorites.</td>', 'Lovely shot, one of my favorites.', '2009-10-08 18:33:31.000000', NULL, 1),
(5680855, 826130, 12674, '<td valign="top">Cute cat, nice shot!</td>', 'Cute cat, nice shot!', '2009-10-08 18:34:34.000000', NULL, 1),
(5680856, 825844, 12674, '<td valign="top">Nice subdued tones and feel. Well done.</td>', 'Nice subdued tones and feel. Well done.', '2009-10-08 18:36:29.000000', NULL, 1),
(5680864, 826209, 89228, '<td valign="top">Superb shot</td>', 'Superb shot', '2009-10-08 18:55:01.000000', NULL, 1),
(5680942, 826107, 110292, '<td valign="top">Meets Challenge: 3 of 3.<br/>Technical: 2 of 3. Something about those leaves in the background distract me, and I''d prefer it was a closer crop so I can see more detail.<br/>Emotion: 2 of 3. I''m reminded of high school when the girls would hang roses upside down to save them, and of my wedding where my wife had her bouquet preserved. Those were good times, so thanks for reminding me of them.<br/>Awe: 0 of 1.</td>', 'Meets Challenge: 3 of 3.Technical: 2 of 3. Something about those leaves in the background distract me, and I''d prefer it was a closer crop so I can see more detail.Emotion: 2 of 3. I''m reminded of high school when the girls would hang roses upside down to save them, and of my wedding where my wife had her bouquet preserved. Those were good times, so thanks for reminding me of them.Awe: 0 of 1.', '2009-10-08 20:31:17.000000', NULL, 1),
(5680950, 825883, 110292, '<td valign="top">Meets Challenge: 2 of 3. This is really borderline for me.  The super bright lower corner is almost too much.<br/>Technical: 1 of 3. Lower right is way overblown, and it feels as though the whole image is out of focus.<br/>Emotion: 1 of 3. I like the little cap, makes the otherwise rigid statue a little more whimsical. But otherwise, it''s just not doin'' it for me.<br/>Awe: 0 of 1.</td>', 'Meets Challenge: 2 of 3. This is really borderline for me.  The super bright lower corner is almost too much.Technical: 1 of 3. Lower right is way overblown, and it feels as though the whole image is out of focus.Emotion: 1 of 3. I like the little cap, makes the otherwise rigid statue a little more whimsical. But otherwise, it''s just not doin'' it for me.Awe: 0 of 1.', '2009-10-08 20:38:32.000000', NULL, 1),
(5680951, 826169, 76598, '<td valign="top">I like the contrast, the angle and the tone in the image.  The curved part of the instrument detracts from the image.</td>', 'I like the contrast, the angle and the tone in the image.  The curved part of the instrument detracts from the image.', '2009-10-08 20:38:39.000000', NULL, 1),
(5680954, 825833, 76598, '<td valign="top">Very cool, love how the light plays around the church and the tone of the image is incredible.  I just wish that "hot spot" to the left of the church wasn''t there.  Not wild about the key stoning.</td>', 'Very cool, love how the light plays around the church and the tone of the image is incredible.  I just wish that "hot spot" to the left of the church wasn''t there.  Not wild about the key stoning.', '2009-10-08 20:40:33.000000', NULL, 1),
(5680955, 826143, 76598, '<td valign="top">The light is too balanced for my tastes, one light source should have been weaker than the other.</td>', 'The light is too balanced for my tastes, one light source should have been weaker than the other.', '2009-10-08 20:41:23.000000', NULL, 1),
(5680958, 825657, 76598, '<td valign="top">A little too dark, I am referring to the lighting....not the content.</td>', 'A little too dark, I am referring to the lighting....not the content.', '2009-10-08 20:43:11.000000', NULL, 1),
(5680959, 825534, 110292, '<td valign="top">Meets Challenge: 3 of 3.<br/>Technical: 1 of 3. The crop is good, but the graininess in the black is ruining it for me.  I know in real life that cat is sleek and smooth and awesome, but here she looks like she''s been attacked by a blackboard eraser.  Maybe a lower film speed and a longer exposure? Tough with live subjects, I know...<br/>Emotion: 2 of 3. That''s a very cool cat. The shadows of her eyelids in her eyes make it look like she very distrustful of whatever she''s looking at.<br/>Awe: 0 of 1.</td>', 'Meets Challenge: 3 of 3.Technical: 1 of 3. The crop is good, but the graininess in the black is ruining it for me.  I know in real life that cat is sleek and smooth and awesome, but here she looks like she''s been attacked by a blackboard eraser.  Maybe a lower film speed and a longer exposure? Tough with live subjects, I know...Emotion: 2 of 3. That''s a very cool cat. The shadows of her eyelids in her eyes make it look like she very distrustful of whatever she''s looking at.Awe: 0 of 1.', '2009-10-08 20:43:38.000000', NULL, 1),
(5680960, 825866, 76598, '<td valign="top">Simple, but very elegant, love the tone in the image.</td>', 'Simple, but very elegant, love the tone in the image.', '2009-10-08 20:43:59.000000', NULL, 1),
(5680961, 825136, 76598, '<td valign="top">The flowers are bright enough that they detract from the full image.  It took me a moment to realize that they were laying on a body.....or is it a body (reflection).</td>', 'The flowers are bright enough that they detract from the full image.  It took me a moment to realize that they were laying on a body.....or is it a body (reflection).', '2009-10-08 20:46:31.000000', NULL, 1),
(5680962, 825581, 76598, '<td valign="top">The graininess doesn''t appeal to me, it might look good in a larger size.</td>', 'The graininess doesn''t appeal to me, it might look good in a larger size.', '2009-10-08 20:47:10.000000', NULL, 1),
(5680963, 826074, 76598, '<td valign="top">very nice, good composition and crisp reflection.</td>', 'very nice, good composition and crisp reflection.', '2009-10-08 20:48:04.000000', NULL, 1),
(5680965, 825127, 76598, '<td valign="top">The light in the light is very bright relative to the remainder of the image....too bright.</td>', 'The light in the light is very bright relative to the remainder of the image....too bright.', '2009-10-08 20:49:15.000000', NULL, 1),
(5680966, 826235, 76598, '<td valign="top">too dark</td>', 'too dark', '2009-10-08 20:50:52.000000', NULL, 1),
(5680969, 825840, 76598, '<td valign="top">really nice, I like this....you may get dinged because folks don''t consider it low key.</td>', 'really nice, I like this....you may get dinged because folks don''t consider it low key.', '2009-10-08 20:52:46.000000', NULL, 1),
(5680970, 826142, 76598, '<td valign="top">strong content, the size of the lady in the image as a whole causes her to get lost a little, it would be much better if it could be displayed larger.</td>', 'strong content, the size of the lady in the image as a whole causes her to get lost a little, it would be much better if it could be displayed larger.', '2009-10-08 20:54:14.000000', NULL, 1),
(5680972, 826115, 76598, '<td valign="top">out of focus, or movement during the shutter release.</td>', 'out of focus, or movement during the shutter release.', '2009-10-08 20:55:58.000000', NULL, 1),
(5680979, 826023, 90414, '<td valign="top">Way too many highlights for low key, imo, but I think this is a creative image.</td>', 'Way too many highlights for low key, imo, but I think this is a creative image.', '2009-10-08 21:03:49.000000', NULL, 1),
(5680981, 825866, 49480, '<td valign="top">Very pretty but doesn''t scream "low key" to me.</td>', 'Very pretty but doesn''t scream "low key" to me.', '2009-10-08 21:04:46.000000', NULL, 1),
(5680982, 826201, 90414, '<td valign="top">Many challenge entries have too many highlights for low key... yours is the opposite for me and has too few highlights. The cats face is mainly in midtones with no real highlights. Also, the composition may have been more effective with the cat less centered in the frame.</td>', 'Many challenge entries have too many highlights for low key... yours is the opposite for me and has too few highlights. The cats face is mainly in midtones with no real highlights. Also, the composition may have been more effective with the cat less centered in the frame.', '2009-10-08 21:07:11.000000', NULL, 1),
(5680995, 825981, 90414, '<td valign="top">Nice dark background, but the entire subject is pretty much in highlights, more than most low key images I have seen.</td>', 'Nice dark background, but the entire subject is pretty much in highlights, more than most low key images I have seen.', '2009-10-08 21:17:22.000000', NULL, 1),
(5680999, 825581, 90414, '<td valign="top">Lovely portrait, but the subject is more in mid-tones than highlights, imo. I like the noise, as I feel it adds texture here.</td>', 'Lovely portrait, but the subject is more in mid-tones than highlights, imo. I like the noise, as I feel it adds texture here.', '2009-10-08 21:19:27.000000', NULL, 1),
(5681005, 826169, 90414, '<td valign="top">One of my favorites of the challenge... unusual in that it is a black object and not just a lit subject against a black bg. Well done.</td>', 'One of my favorites of the challenge... unusual in that it is a black object and not just a lit subject against a black bg. Well done.', '2009-10-08 21:23:53.000000', NULL, 1),
(5681007, 825812, 108525, '<td valign="top">I think a deeper DoF, and portrait crop would have sent this photo''s score up up up .</td>', 'I think a deeper DoF, and portrait crop would have sent this photo''s score up up up .', '2009-10-08 21:26:11.000000', NULL, 1),
(5681017, 825794, 90414, '<td valign="top">Not really dark enough to be truly low key, but I must say this is an impressive and interesting image = extra points!</td>', 'Not really dark enough to be truly low key, but I must say this is an impressive and interesting image = extra points!', '2009-10-08 21:34:19.000000', NULL, 1),
(5681018, 825624, 90414, '<td valign="top">Interesting image, and a perfect ratio of black to highlights for a low key photo. Very well done.</td>', 'Interesting image, and a perfect ratio of black to highlights for a low key photo. Very well done.', '2009-10-08 21:35:48.000000', NULL, 1),
(5681022, 826107, 90414, '<td valign="top">I like this image, might have used a square crop and still had plenty of black bg.</td>', 'I like this image, might have used a square crop and still had plenty of black bg.', '2009-10-08 21:38:26.000000', NULL, 1),
(5681028, 825410, 90414, '<td valign="top">Interesting image, but I think the halos will hurt your score.</td>', 'Interesting image, but I think the halos will hurt your score.', '2009-10-08 21:42:52.000000', NULL, 1),
(5681042, 825309, 90414, '<td valign="top">Too dim imo... not enough highlights for low key.</td>', 'Too dim imo... not enough highlights for low key.', '2009-10-08 21:52:32.000000', NULL, 1),
(5681043, 826121, 108525, '<td valign="top">The lighting seems to lack drama.</td>', 'The lighting seems to lack drama.', '2009-10-08 21:52:50.000000', NULL, 1),
(5681050, 825845, 108525, '<td valign="top">Beautiful colors, but since it''s all blurry it''s hard to tell what I''m looking at.</td>', 'Beautiful colors, but since it''s all blurry it''s hard to tell what I''m looking at.', '2009-10-08 21:58:59.000000', NULL, 1),
(5681054, 826147, 90414, '<td valign="top">Very nice photo, and although it is dark, it''s not black enough for me to see as a true low key image imo. Beautiful blue hour shot.</td>', 'Very nice photo, and although it is dark, it''s not black enough for me to see as a true low key image imo. Beautiful blue hour shot.', '2009-10-08 22:01:25.000000', NULL, 1),
(5681061, 825425, 108525, '<td valign="top">I would crop off the top 1/3 of the photo, and bring the contrast down a hair.</td>', 'I would crop off the top 1/3 of the photo, and bring the contrast down a hair.', '2009-10-08 22:02:29.000000', NULL, 1),
