(5682235, 826173, 96614, '<td valign="top">Nice! great job on the lighting!</td>', 'Nice! great job on the lighting!', '2009-10-09 22:55:26.000000', NULL, 1),
(5682238, 826190, 96614, '<td valign="top">This is an awesome shot, but the background takes away from the presentation... you should make sure to have a solid black background... I can see a wrinkly cloth and it''s a tad distracting... try to put the background further from the cat that it won''t catch the light as much making it darker...playing with the mid tones in the levels adjustment can also help eliminate that background a bit too...</td>', 'This is an awesome shot, but the background takes away from the presentation... you should make sure to have a solid black background... I can see a wrinkly cloth and it''s a tad distracting... try to put the background further from the cat that it won''t catch the light as much making it darker...playing with the mid tones in the levels adjustment can also help eliminate that background a bit too...', '2009-10-09 22:56:29.000000', NULL, 1),
