(5683600, 826065, 83544, '<td valign="top">I can''t say that I love your "california love" photo</td>', 'I can''t say that I love your "california love" photo', '2009-10-11 16:46:49.000000', NULL, 1),
(5683602, 826230, 83544, '<td valign="top">the background is kinda grainy and not equily black everywhere</td>', 'the background is kinda grainy and not equily black everywhere', '2009-10-11 16:47:58.000000', NULL, 1),
(5683604, 825672, 83544, '<td valign="top">nice ride ;-) and photo</td>', 'nice ride ;-) and photo', '2009-10-11 16:49:27.000000', NULL, 1),
(5683610, 826094, 83544, '<td valign="top">nice idea and capture</td>', 'nice idea and capture', '2009-10-11 16:53:40.000000', NULL, 1),
