(5683614, 826107, 83544, '<td valign="top">nice capture but I don''t like the smaller image size</td>', 'nice capture but I don''t like the smaller image size', '2009-10-11 16:56:18.000000', NULL, 1),
(5683618, 825844, 83544, '<td valign="top">wow nice capture, I like the dark blue feeling, except the white frame, for a low key photo it doesn''t fit very much</td>', 'wow nice capture, I like the dark blue feeling, except the white frame, for a low key photo it doesn''t fit very much', '2009-10-11 16:57:42.000000', NULL, 1),
(5683632, 826161, 83544, '<td valign="top">your shot is nice but you have could made the upper left edge black and also on the bottom</td>', 'your shot is nice but you have could made the upper left edge black and also on the bottom', '2009-10-11 17:06:36.000000', NULL, 1),
(5683649, 826210, 83313, '<td valign="top">I gave this a pretty high vote. It fits my concept of low key, and the subject is (for the most part) well outlined by highly contrasting highlights. I did have to look at it a bit to figure out what kind of hat he was wearing. Once I realized what sort of person this was, my impression was that he is waiting for his turn in a rodeo, or something where he is going to have to prove himself. About my only real nitpick is that his hat is hard to make out from the shadows, and recognizing the hat and boots is what gives context to this image. In advanced editing, you could have done some selective editing to pull it out of the shadows a little more. For this one, however, you would have had to light it a little differently to make it stand out. Lighting is one of my own weak areas, so I would be hard pressed to do as well.</td>', 'I gave this a pretty high vote. It fits my concept of low key, and the subject is (for the most part) well outlined by highly contrasting highlights. I did have to look at it a bit to figure out what kind of hat he was wearing. Once I realized what sort of person this was, my impression was that he is waiting for his turn in a rodeo, or something where he is going to have to prove himself. About my only real nitpick is that his hat is hard to make out from the shadows, and recognizing the hat and boots is what gives context to this image. In advanced editing, you could have done some selective editing to pull it out of the shadows a little more. For this one, however, you would have had to light it a little differently to make it stand out. Lighting is one of my own weak areas, so I would be hard pressed to do as well.', '2009-10-11 17:41:05.000000', NULL, 1),
(5683684, 826075, 33732, '<td valign="top">Nice. Shadows are nice as well.  A little lighter for the moon maybe.</td>', 'Nice. Shadows are nice as well.  A little lighter for the moon maybe.', '2009-10-11 18:28:34.000000', NULL, 1),
