(5684938, 825903, 5746, '<td valign="top">I like strong contrast here. It has somehow industrial feel. Pleasant pattern and very strong rhythm. 9.</td>', 'I like strong contrast here. It has somehow industrial feel. Pleasant pattern and very strong rhythm. 9.', '2009-10-12 19:13:28.000000', NULL, 1),
(5684940, 826212, 5746, '<td valign="top">Excellent study. I like limited color scheme and composition. Great detail. 9.</td>', 'Excellent study. I like limited color scheme and composition. Great detail. 9.', '2009-10-12 19:13:56.000000', NULL, 1),
(5684942, 825877, 5746, '<td valign="top">So serious. Intense. Very nice portrait. 8.</td>', 'So serious. Intense. Very nice portrait. 8.', '2009-10-12 19:14:24.000000', NULL, 1),
(5684943, 826229, 5746, '<td valign="top">Such a warm smile. Very nice portrait. 8.</td>', 'Such a warm smile. Very nice portrait. 8.', '2009-10-12 19:15:00.000000', NULL, 1),
(5684945, 825855, 5746, '<td valign="top">The clouds are like from a Turner painting. Wonderful effect. I like the colors, but it''s the sky which is the center point. I would''ve recompose to crop the lower part. But the sky - magnificent! 8.</td>', 'The clouds are like from a Turner painting. Wonderful effect. I like the colors, but it''s the sky which is the center point. I would''ve recompose to crop the lower part. But the sky - magnificent! 8.', '2009-10-12 19:16:30.000000', NULL, 1),
(5684946, 825309, 5746, '<td valign="top">I have to bump it. This challenge is so difficult to vote - too many excellent pictures - including yours of course. I like the way you presented such a delicate glow. Must''ve been a challenge. 10.</td>', 'I have to bump it. This challenge is so difficult to vote - too many excellent pictures - including yours of course. I like the way you presented such a delicate glow. Must''ve been a challenge. 10.', '2009-10-12 19:17:38.000000', NULL, 1),
(5684947, 826101, 5746, '<td valign="top">Excellent quality and detail. I like the touch of color. 8.</td>', 'Excellent quality and detail. I like the touch of color. 8.', '2009-10-12 19:18:14.000000', NULL, 1),
(5684948, 826188, 5746, '<td valign="top">Standing pear looks a bit awkward. However... wonderful color scheme - painting like, very well composed, nice DOF, great detail. Bumping up to 9.</td>', 'Standing pear looks a bit awkward. However... wonderful color scheme - painting like, very well composed, nice DOF, great detail. Bumping up to 9.', '2009-10-12 19:19:34.000000', NULL, 1),
(5684974, 825798, 109728, '<td valign="top">very well done</td>', 'very well done', '2009-10-12 19:38:10.000000', NULL, 1),
(5684976, 826048, 109728, '<td valign="top">interesting, but i wouldn''t define it as low key myself.</td>', 'interesting, but i wouldn''t define it as low key myself.', '2009-10-12 19:38:41.000000', NULL, 1);
