(5685325, 826090, 109353, '<td valign="top">Nice work. Excellent light and use of DOF.<br/>I think you played too much with the curves in post-processing: the grayscale creates some shapes inside the waves (but maybe I''m wrong) ... 8</td>', 'Nice work. Excellent light and use of DOF.I think you played too much with the curves in post-processing: the grayscale creates some shapes inside the waves (but maybe I''m wrong) ... 8', '2009-10-13 08:01:18.000000', NULL, 1),
(5685575, 825840, 110901, '<td valign="top">Is this low key??</td>', 'Is this low key??', '2009-10-13 14:33:53.000000', NULL, 1),
