(5685844, 826132, 76335, '<td valign="top">The title nails it and probably bought you a couple points. I saw an entirely different image after you biased me. Great shot!</td>', 'The title nails it and probably bought you a couple points. I saw an entirely different image after you biased me. Great shot!', '2009-10-13 19:21:04.000000', NULL, 1),
(5685845, 825709, 76335, '<td valign="top">One of the more interesting and original floral shots here.</td>', 'One of the more interesting and original floral shots here.', '2009-10-13 19:21:26.000000', NULL, 1),
(5685846, 826208, 76335, '<td valign="top">Excellent!</td>', 'Excellent!', '2009-10-13 19:23:11.000000', NULL, 1),
