(5685853, 825812, 76335, '<td valign="top">Dark and gritty and very cool.</td>', 'Dark and gritty and very cool.', '2009-10-13 19:31:32.000000', NULL, 1),
(5685854, 826207, 76335, '<td valign="top">Excellent! I''m glad the black shirt wasn''t lost to the background which would have been the temptation of many photographers (and probably this one).</td>', 'Excellent! I''m glad the black shirt wasn''t lost to the background which would have been the temptation of many photographers (and probably this one).', '2009-10-13 19:33:02.000000', NULL, 1),
